import unittest

from hourglass.models import Span
from hourglass.rounding import label_spans


class LabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        out = label_spans([Span(543, 1034)], 15)
        self.assertEqual(out, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        out = label_spans([Span(545, 600)], 10)
        self.assertEqual(out, ["09:10-10:00 (0h 50m)"])

    def test_one_label_per_span(self):
        spans = [Span(480, 720), Span(780, 1020)]
        out = label_spans(spans, 30)
        self.assertEqual(len(out), 2)

    def test_empty(self):
        self.assertEqual(label_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                label_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
